{"code":"import json
import numpy as np
import pandas as pd

with open("evaluations.json") as f:
    data = json.load(f)

rows = []
for d in data:
    rec = {x["ingredient"]: x["fraction"] for x in d["recipe"]}
    if "soymilk" in rec and "olive oil" not in rec:
        rows.append({
            "iter": d["iteration"],
            "soymilk": rec["soymilk"],
            "oil": rec["coconut oil"],
            "spi": rec["soy protein isolate"],
            "starch": rec["tapioca starch"],
            "y": d["target_dissimilarity"]
        })

df = pd.DataFrame(rows)
print(df.sort_values("y"))
